def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    colors = {v for row in g for v in row}
    bg = max(colors, key=lambda c: sum(row.count(c) for row in g))

    # Find the full-width or full-height marker stripe.
    marker = None
    for r, row in enumerate(g):
        if len(set(row)) == 1 and row[0] != bg:
            marker = ('h', r, row[0])
            break
    if marker is None:
        for c in range(w):
            if len({g[r][c] for r in range(h)}) == 1 and g[0][c] != bg:
                marker = ('v', c, g[0][c])
                break
    if marker is None:
        return g

    figure_color = max(
        (c for c in colors if c not in (bg, marker[2])),
        key=lambda c: sum(row.count(c) for row in g)
    )
    points = [(r, c) for r in range(h) for c in range(w) if g[r][c] == figure_color]

    if marker[0] == 'h':
        mr = marker[1]
        top = min(r for r, c in points)
        bottom = max(r for r, c in points)
        if mr > bottom:
            shift = mr - 1 - bottom
            divider = top + shift - 1
        else:
            shift = mr + 1 - top
            divider = bottom + shift + 1
        for r, c in points:
            g[r][c] = bg
        moved = [(r + shift, c) for r, c in points]
        for r, c in moved:
            g[r][c] = figure_color
        if 0 <= divider < h:
            g[divider] = [8] * w
    else:
        mc = marker[1]
        left = min(c for r, c in points)
        right = max(c for r, c in points)
        if mc > right:
            shift = mc - 1 - right
            divider = left + shift - 1
        else:
            shift = mc + 1 - left
            divider = right + shift + 1
        for r, c in points:
            g[r][c] = bg
        moved = [(r, c + shift) for r, c in points]
        for r, c in moved:
            g[r][c] = figure_color
        if 0 <= divider < w:
            for r in range(h):
                g[r][divider] = 8
    return g
